/**
 * Port for binary object storage (profile photos now; media later). Keys are
 * generated by the server — never derived from client filenames — and
 * validated by every adapter. Production will use an S3-compatible adapter.
 */
export abstract class ObjectStorage {
  /** False when no storage is configured; uploads are then refused. */
  abstract readonly enabled: boolean;
  abstract put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** Returns the object, or undefined if it does not exist. */
  abstract get(key: string): Promise<Buffer | undefined>;
  /** Idempotent: deleting a missing object is not an error. */
  abstract delete(key: string): Promise<void>;
}

/**
 * `avatars/<uuid>.webp`, `attachments/<uuid>.bin` (ciphertext) or
 * `channel-media/<uuid>.(webp|bin)` (community channel media, server-readable) —
 * nothing else is a valid key.
 */
export const STORAGE_KEY_PATTERN =
  /^(?:avatars\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp|attachments\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.bin|channel-media\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(?:webp|bin))$/;

export function assertValidKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) {
    throw new Error('Invalid storage key');
  }
}
